const content={claude:{label:'在 Claude Code 中安装',install:'/plugin marketplace add realhenrylo/agent-room\n/plugin install agent-room@agent-room-marketplace',room:'/agent-room:agent-room create --name my-team',note:'在项目会话中运行命令。把生成的房间码发给同事，对方使用 join 加入。',guide:'https://github.com/realhenrylo/agent-room#per-colleague'},codex:{label:'在终端中安装',install:'codex plugin marketplace add realhenrylo/agent-room\ncodex plugin add agent-room@agent-room-marketplace',room:'$agent-room create',note:'需要 Node.js 20+ 和支持插件、codex queue 的 Codex CLI。安装后开启新会话，通过 /hooks 审核并信任生命周期 hooks，再运行创建命令。',guide:'https://github.com/realhenrylo/agent-room/blob/main/docs/codex.md'}};
const tabs=[...document.querySelectorAll('[data-host]')];
function selectHost(tab){const data=content[tab.dataset.host];tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});document.getElementById('install-panel').setAttribute('aria-labelledby',tab.id);document.getElementById('command-label').textContent=data.label;document.getElementById('install-command').textContent=data.install;document.getElementById('room-command').textContent=data.room;document.getElementById('host-note').textContent=data.note;document.getElementById('guide-link').href=data.guide;}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectHost(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight'||event.key==='ArrowLeft')next=tabs[(index+1)%tabs.length];if(event.key==='Home')next=tabs[0];if(event.key==='End')next=tabs[tabs.length-1];if(next){event.preventDefault();selectHost(next);next.focus()}})});
let toastTimer;function notify(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),2600)}
document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const element=document.getElementById(button.dataset.copy);try{await navigator.clipboard.writeText(element.textContent);notify('命令已复制，去召集队友吧！')}catch{const selection=window.getSelection();const range=document.createRange();range.selectNodeContents(element);selection.removeAllRanges();selection.addRange(range);notify('请按 Ctrl+C / ⌘C 复制选中的命令')}}));
